import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import * as SelectPrimitive from "@kobalte/core/select";

import { cn } from "~/lib/utils.ts";

import type { Component, ComponentProps, JSX, ValidComponent } from "solid-js";
import { mergeProps, splitProps } from "solid-js";
import IconCheck from "~icons/lucide/check";
import IconChevronDown from "~icons/lucide/chevron-down";

// Unlike radix, Kobalte's Root renders a real <div> wrapping the
// trigger, so the slot marks the element grouped containers (e.g.
// button-group) match on.
const Select = <Option, OptGroup = never, T extends ValidComponent = "div">(
  props: PolymorphicProps<
    T,
    SelectPrimitive.SelectRootProps<Option, OptGroup, T>
  >,
) => (
  <SelectPrimitive.Root
    data-slot="select"
    {...(props as SelectPrimitive.SelectRootProps<Option, OptGroup>)}
  />
);

const SelectHiddenSelect = SelectPrimitive.HiddenSelect;

type SelectValueProps<Option, T extends ValidComponent = "span"> =
  SelectPrimitive.SelectValueProps<Option, T>;

const SelectValue = <Option, T extends ValidComponent = "span">(
  props: PolymorphicProps<T, SelectValueProps<Option, T>>,
) => (
  <SelectPrimitive.Value
    data-slot="select-value"
    {...(props as SelectValueProps<Option>)}
  />
);

type SelectTriggerProps<T extends ValidComponent = "button"> =
  & SelectPrimitive.SelectTriggerProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
    size?: "sm" | "default";
  };

const SelectTrigger = <T extends ValidComponent = "button">(
  rawProps: PolymorphicProps<T, SelectTriggerProps<T>>,
) => {
  const props = mergeProps(
    { size: "default" as const },
    rawProps as SelectTriggerProps,
  );
  const [local, others] = splitProps(props, ["class", "children", "size"]);
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={local.size}
      class={cn(
        "bg-input/50 border-transparent has-data-placeholder-shown:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 gap-1.5 rounded-2xl border py-2 px-3 text-sm transition-[color,box-shadow] duration-200 focus-visible:ring-3 aria-invalid:ring-3 data-[size=default]:h-8 data-[size=sm]:h-7 *:data-[slot=select-value]:gap-1.5 [&_svg:not([class*='size-'])]:size-4 data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 data-invalid:border-destructive dark:data-invalid:border-destructive/50 data-invalid:ring-3 flex w-fit items-center justify-between whitespace-nowrap outline-none data-disabled:cursor-not-allowed data-disabled:opacity-50 *:data-[slot=select-value]:line-clamp-1 *:data-[slot=select-value]:flex *:data-[slot=select-value]:items-center [&_svg]:pointer-events-none [&_svg]:shrink-0",
        local.class,
      )}
      {...others}
    >
      {local.children}
      <SelectPrimitive.Icon>
        <IconChevronDown
          class="text-muted-foreground size-4 pointer-events-none"
        />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
};

type SelectContentProps<T extends ValidComponent = "div"> =
  & SelectPrimitive.SelectContentProps<T>
  & { class?: string | undefined };

// Kobalte builds the list from the `options` collection instead of
// children, so the listbox (radix's Viewport) is rendered here rather
// than composed by the consumer.
const SelectContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, SelectContentProps<T>>,
) => {
  const [local, others] = splitProps(props as SelectContentProps, ["class"]);
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        data-slot="select-content"
        class={cn(
          "bg-popover text-popover-foreground data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 ring-foreground/5 dark:ring-foreground/10 min-w-36 rounded-2xl shadow-lg ring-1 duration-100 relative z-50 origin-(--kb-select-content-transform-origin) overflow-hidden",
          local.class,
        )}
        {...others}
      >
        <SelectPrimitive.Listbox
          data-slot="select-list"
          class="max-h-(--kb-popper-content-available-height) scroll-py-1.5 overflow-y-auto overscroll-contain p-1"
        />
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
};

// Kobalte's Section is the group heading itself (the listbox is flat),
// so it carries radix SelectLabel's slot and marker.
type SelectSectionProps<T extends ValidComponent = "li"> =
  & SelectPrimitive.SelectSectionProps<T>
  & { class?: string | undefined };

const SelectSection = <T extends ValidComponent = "li">(
  props: PolymorphicProps<T, SelectSectionProps<T>>,
) => {
  const [local, others] = splitProps(props as SelectSectionProps, ["class"]);
  return (
    <SelectPrimitive.Section
      data-slot="select-label"
      class={cn("text-muted-foreground px-2 py-1 text-xs", local.class)}
      {...others}
    />
  );
};

// Kobalte has no Select.Separator; the listbox renders from the
// collection, so a separator is a plain presentational element emitted
// from `sectionComponent`.
// an li, not a div: the listbox is a ul, which may only own list items
const SelectSeparator: Component<ComponentProps<"li">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <li
      data-slot="select-separator"
      role="separator"
      aria-orientation="horizontal"
      class={cn("bg-border -mx-1 my-1 h-px pointer-events-none", local.class)}
      {...others}
    />
  );
};

type SelectItemProps<T extends ValidComponent = "li"> =
  & SelectPrimitive.SelectItemProps<T>
  & {
    class?: string | undefined;
    children?: JSX.Element;
  };

// Kobalte's ItemLabel defaults to a div; radix's ItemText is a span and
// the nova item block targets the last span child, so it renders as one.
const SelectItem = <T extends ValidComponent = "li">(
  props: PolymorphicProps<T, SelectItemProps<T>>,
) => {
  const [local, others] = splitProps(props as SelectItemProps, [
    "class",
    "children",
  ]);
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      class={cn(
        "data-highlighted:bg-accent gap-2 min-h-7 rounded-xl py-1.5 pr-8 pl-2 text-sm [&_svg:not([class*='size-'])]:size-4 *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2 data-highlighted:text-accent-foreground not-data-[variant=destructive]:data-highlighted:**:text-accent-foreground relative flex w-full cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
        local.class,
      )}
      {...others}
    >
      <span class="pointer-events-none absolute right-2 flex size-4 items-center justify-center">
        <SelectPrimitive.ItemIndicator as="span">
          <IconCheck
            class="pointer-events-none"
          />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemLabel as="span">
        {local.children}
      </SelectPrimitive.ItemLabel>
    </SelectPrimitive.Item>
  );
};

export {
  Select,
  SelectContent,
  SelectHiddenSelect,
  SelectItem,
  SelectSection,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};
